-- TravelWell.World — the daily advisory checker's scheduled job.
--
-- GENERATED by `npm run gen:advisory-payload` — do not hand-edit. The country
-- payload below must be byte-identical to docs/advisory-countries.json, which is
-- why one command writes both. Editing this file by hand reintroduces exactly
-- the drift the generator exists to prevent.
--
-- Re-runnable: unschedules the existing job before scheduling the new one, so
-- applying it again after a regeneration is the correct and only step.
--
-- BEFORE APPLYING, two things must already exist. Both are checked below and
-- fail loudly rather than leaving a job that can never authenticate:
--   1. pg_cron and pg_net enabled (Dashboard → Database → Extensions).
--   2. The service-role key in Vault under the name 'advisory_check_key':
--        select vault.create_secret('<service-role-key>', 'advisory_check_key',
--                                   'Daily advisory checker');
--      It goes in Vault and not in this file because cron.schedule stores its
--      command as readable plain text in cron.job. A key pasted into a job is a
--      key sitting in a table forever, and this file is in a git repo besides.
--
-- Apply: paste into the Supabase SQL editor. Requires 0013 and 0014.

do $guard$
begin
  if not exists (select 1 from pg_extension where extname = 'pg_cron') then
    raise exception 'pg_cron is not enabled. Dashboard → Database → Extensions → pg_cron, then re-run this migration.';
  end if;
  if not exists (select 1 from pg_extension where extname = 'pg_net') then
    raise exception 'pg_net is not enabled. Dashboard → Database → Extensions → pg_net, then re-run this migration.';
  end if;
  if not exists (select 1 from vault.decrypted_secrets where name = 'advisory_check_key') then
    raise exception 'Vault secret advisory_check_key is missing. Create it first (see the header of this file) — a job scheduled without it would fail 401 every morning and still look scheduled.';
  end if;
  -- A key stored with a stray newline breaks the request in a way that looks
  -- nothing like a key problem. See the note above the Authorization header.
  if exists (select 1 from vault.decrypted_secrets
             where name = 'advisory_check_key'
               and trim(both E' \t\r\n' from decrypted_secret) ~ '\s') then
    raise exception 'The stored advisory_check_key contains whitespace inside it — that is a corrupted paste, not a key. Re-create the secret from a clean copy.';
  end if;
end
$guard$;

-- Replace any previous version of the job (a regenerated payload lands here).
select cron.unschedule('advisory-check-daily')
where exists (select 1 from cron.job where jobname = 'advisory-check-daily');

-- 06:00 UTC daily. The FCDO publishes on London business hours, so an early-UTC
-- run reads yesterday's settled state rather than a page mid-edit, and whatever
-- it queues is waiting when someone opens the laptop.
select cron.schedule(
  'advisory-check-daily',
  '0 6 * * *',
  $job$
  select net.http_post(
    url     := 'https://xgjidkgctqqdprxtxeui.supabase.co/functions/v1/advisory-check',
    -- TRIM IS LORE, NOT TIDINESS. A key copied with a trailing newline makes the
    -- header value end in a line break; pg_net then writes its own CRLF after it,
    -- and the two together form the blank line that ENDS the header section. Every
    -- header pg_net adds next — User-Agent, Content-Length — plus the JSON lands
    -- in the body instead. The function then reports a malformed body, which
    -- points at the payload and never at the key. Cost us an afternoon; the fix is
    -- one function call and it belongs here permanently.
    headers := jsonb_build_object(
                 'Content-Type', 'application/json',
                 'Authorization', 'Bearer ' || (
                   select trim(both E' \t\r\n' from decrypted_secret)
                   from vault.decrypted_secrets
                   where name = 'advisory_check_key')),
    body    := $json${"countries":[{"iso":"AE","name":"United Arab Emirates","match":["united arab emirates"],"fcdo_slug":"united-arab-emirates"},{"iso":"AE","name":"UAE","match":["uae","united arab emirates"],"fcdo_slug":"united-arab-emirates"},{"iso":"AI","name":"Anguilla","match":["anguilla"],"fcdo_slug":"anguilla"},{"iso":"AR","name":"Argentina","match":["argentina"],"fcdo_slug":"argentina"},{"iso":"AT","name":"Austria","match":["austria"],"fcdo_slug":"austria"},{"iso":"AU","name":"Australia","match":["australia"],"fcdo_slug":"australia"},{"iso":"AW","name":"Aruba","match":["aruba"],"fcdo_slug":"aruba"},{"iso":"BB","name":"Barbados","match":["barbados"],"fcdo_slug":"barbados"},{"iso":"BE","name":"Belgium","match":["belgium"],"fcdo_slug":"belgium"},{"iso":"BL","name":"St. Barthélemy (France/EU)","match":["st. barthélemy (france/eu)","st martin and st barthelemy"],"fcdo_slug":"st-martin-and-st-barthelemy"},{"iso":"BQ","name":"Sint Eustatius","match":["sint eustatius","bonaire st eustatius saba"],"fcdo_slug":"bonaire-st-eustatius-saba"},{"iso":"BQ","name":"Bonaire","match":["bonaire"],"fcdo_slug":"bonaire"},{"iso":"BQ","name":"Saba","match":["saba"],"fcdo_slug":"saba"},{"iso":"BR","name":"Brazil","match":["brazil"],"fcdo_slug":"brazil"},{"iso":"BS","name":"Bahamas","match":["bahamas"],"fcdo_slug":"bahamas"},{"iso":"BW","name":"Botswana","match":["botswana"],"fcdo_slug":"botswana"},{"iso":"BZ","name":"Belize","match":["belize"],"fcdo_slug":"belize"},{"iso":"CA","name":"Canada","match":["canada"],"fcdo_slug":"canada"},{"iso":"CH","name":"Switzerland","match":["switzerland"],"fcdo_slug":"switzerland"},{"iso":"CL","name":"Chile","match":["chile"],"fcdo_slug":"chile"},{"iso":"CO","name":"Colombia","match":["colombia"],"fcdo_slug":"colombia"},{"iso":"CR","name":"Costa Rica","match":["costa rica"],"fcdo_slug":"costa-rica"},{"iso":"CW","name":"Curaçao","match":["curaçao","curacao"],"fcdo_slug":"curacao"},{"iso":"DE","name":"Germany","match":["germany"],"fcdo_slug":"germany"},{"iso":"DK","name":"Denmark","match":["denmark"],"fcdo_slug":"denmark"},{"iso":"DM","name":"Dominica","match":["dominica"],"fcdo_slug":"dominica"},{"iso":"DO","name":"Dominican Republic","match":["dominican republic"],"fcdo_slug":"dominican-republic"},{"iso":"EC","name":"Ecuador","match":["ecuador"],"fcdo_slug":"ecuador"},{"iso":"EE","name":"Estonia","match":["estonia"],"fcdo_slug":"estonia"},{"iso":"EG","name":"Egypt","match":["egypt"],"fcdo_slug":"egypt"},{"iso":"ES","name":"Spain","match":["spain"],"fcdo_slug":"spain"},{"iso":"ET","name":"Ethiopia","match":["ethiopia"],"fcdo_slug":"ethiopia"},{"iso":"FI","name":"Finland","match":["finland"],"fcdo_slug":"finland"},{"iso":"FO","name":"Faroe Islands (Kingdom of Denmark)","match":["faroe islands (kingdom of denmark)","denmark"],"fcdo_slug":"denmark"},{"iso":"FR","name":"France","match":["france"],"fcdo_slug":"france"},{"iso":"GD","name":"Grenada","match":["grenada"],"fcdo_slug":"grenada"},{"iso":"GP","name":"Guadeloupe","match":["guadeloupe"],"fcdo_slug":"guadeloupe"},{"iso":"GR","name":"Greece","match":["greece"],"fcdo_slug":"greece"},{"iso":"GT","name":"Guatemala","match":["guatemala"],"fcdo_slug":"guatemala"},{"iso":"HN","name":"Honduras","match":["honduras"],"fcdo_slug":"honduras"},{"iso":"HR","name":"Croatia","match":["croatia"],"fcdo_slug":"croatia"},{"iso":"HU","name":"Hungary","match":["hungary"],"fcdo_slug":"hungary"},{"iso":"ID","name":"Indonesia","match":["indonesia"],"fcdo_slug":"indonesia"},{"iso":"IE","name":"Ireland","match":["ireland"],"fcdo_slug":"ireland"},{"iso":"IS","name":"Iceland","match":["iceland"],"fcdo_slug":"iceland"},{"iso":"IT","name":"Italy","match":["italy"],"fcdo_slug":"italy"},{"iso":"JM","name":"Jamaica","match":["jamaica"],"fcdo_slug":"jamaica"},{"iso":"JO","name":"Jordan","match":["jordan"],"fcdo_slug":"jordan"},{"iso":"JP","name":"Japan","match":["japan"],"fcdo_slug":"japan"},{"iso":"KE","name":"Kenya","match":["kenya"],"fcdo_slug":"kenya"},{"iso":"KH","name":"Cambodia","match":["cambodia"],"fcdo_slug":"cambodia"},{"iso":"KN","name":"St. Kitts & Nevis","match":["st. kitts & nevis","st kitts and nevis"],"fcdo_slug":"st-kitts-and-nevis"},{"iso":"KR","name":"South Korea","match":["south korea"],"fcdo_slug":"south-korea"},{"iso":"LA","name":"Laos","match":["laos"],"fcdo_slug":"laos"},{"iso":"LC","name":"St. Lucia","match":["st. lucia","st lucia"],"fcdo_slug":"st-lucia"},{"iso":"LU","name":"Luxembourg","match":["luxembourg"],"fcdo_slug":"luxembourg"},{"iso":"MA","name":"Morocco","match":["morocco"],"fcdo_slug":"morocco"},{"iso":"MC","name":"Monaco","match":["monaco"],"fcdo_slug":"monaco"},{"iso":"MQ","name":"Martinique","match":["martinique"],"fcdo_slug":"martinique"},{"iso":"MS","name":"Montserrat","match":["montserrat"],"fcdo_slug":"montserrat"},{"iso":"MT","name":"Malta","match":["malta"],"fcdo_slug":"malta"},{"iso":"MV","name":"Maldives","match":["maldives"],"fcdo_slug":"maldives"},{"iso":"MX","name":"Mexico","match":["mexico"],"fcdo_slug":"mexico"},{"iso":"MZ","name":"Mozambique","match":["mozambique"],"fcdo_slug":"mozambique"},{"iso":"NA","name":"Namibia","match":["namibia"],"fcdo_slug":"namibia"},{"iso":"NI","name":"Nicaragua","match":["nicaragua"],"fcdo_slug":"nicaragua"},{"iso":"NL","name":"Netherlands","match":["netherlands"],"fcdo_slug":"netherlands"},{"iso":"NO","name":"Norway","match":["norway"],"fcdo_slug":"norway"},{"iso":"NZ","name":"New Zealand","match":["new zealand"],"fcdo_slug":"new-zealand"},{"iso":"OM","name":"Oman","match":["oman"],"fcdo_slug":"oman"},{"iso":"PA","name":"Panama","match":["panama"],"fcdo_slug":"panama"},{"iso":"PE","name":"Peru","match":["peru"],"fcdo_slug":"peru"},{"iso":"PF","name":"French Polynesia","match":["french polynesia"],"fcdo_slug":"french-polynesia"},{"iso":"PH","name":"Philippines","match":["philippines"],"fcdo_slug":"philippines"},{"iso":"PR","name":"Puerto Rico (US territory)","match":["puerto rico (us territory)","usa"],"fcdo_slug":"usa"},{"iso":"PT","name":"Portugal","match":["portugal"],"fcdo_slug":"portugal"},{"iso":"PW","name":"Palau","match":["palau"],"fcdo_slug":"palau"},{"iso":"QA","name":"Qatar","match":["qatar"],"fcdo_slug":"qatar"},{"iso":"RW","name":"Rwanda","match":["rwanda"],"fcdo_slug":"rwanda"},{"iso":"SA","name":"Saudi Arabia","match":["saudi arabia"],"fcdo_slug":"saudi-arabia"},{"iso":"SE","name":"Sweden","match":["sweden"],"fcdo_slug":"sweden"},{"iso":"SI","name":"Slovenia","match":["slovenia"],"fcdo_slug":"slovenia"},{"iso":"SV","name":"El Salvador","match":["el salvador"],"fcdo_slug":"el-salvador"},{"iso":"TC","name":"Turks & Caicos","match":["turks & caicos","turks and caicos islands"],"fcdo_slug":"turks-and-caicos-islands"},{"iso":"TH","name":"Thailand","match":["thailand"],"fcdo_slug":"thailand"},{"iso":"TN","name":"Tunisia","match":["tunisia"],"fcdo_slug":"tunisia"},{"iso":"TZ","name":"Tanzania","match":["tanzania"],"fcdo_slug":"tanzania"},{"iso":"UG","name":"Uganda","match":["uganda"],"fcdo_slug":"uganda"},{"iso":"US","name":"United States","match":["united states","usa"],"fcdo_slug":"usa"},{"iso":"UY","name":"Uruguay","match":["uruguay"],"fcdo_slug":"uruguay"},{"iso":"VC","name":"St. Vincent & the Grenadines","match":["st. vincent & the grenadines","st vincent and the grenadines"],"fcdo_slug":"st-vincent-and-the-grenadines"},{"iso":"VG","name":"British Virgin Islands","match":["british virgin islands"],"fcdo_slug":"british-virgin-islands"},{"iso":"VI","name":"US Virgin Islands (US territory)","match":["us virgin islands (us territory)","usa"],"fcdo_slug":"usa"},{"iso":"VN","name":"Vietnam","match":["vietnam"],"fcdo_slug":"vietnam"},{"iso":"ZA","name":"South Africa","match":["south africa"],"fcdo_slug":"south-africa"},{"iso":"ZM","name":"Zambia","match":["zambia"],"fcdo_slug":"zambia"},{"iso":"ZW","name":"Zimbabwe","match":["zimbabwe"],"fcdo_slug":"zimbabwe"}]}$json$::jsonb,
    -- pg_net defaults to 5s. The timeout can't break a run — http_post is
    -- asynchronous, so the function completes server-side either way — but at
    -- 5s net._http_response records a timeout instead of the run summary, and
    -- the first place anyone looks after a bad morning shows an error that
    -- never happened. 97 countries, one request each.
    timeout_milliseconds := 120000
  )
  $job$
);

